import { join } from 'node:path'
import { app } from 'electron'

// In development, files are read from the project folder.
// In production, electron-builder copies them next to the app (see `extraResources`).
const root = app.isPackaged ? process.resourcesPath : app.getAppPath()

/** Path of a file in the `resources/` folder (icons, tray images…). */
export function resourcePath(...segments: string[]): string {
  return join(root, 'resources', ...segments)
}

/** Folder containing the SQL migrations generated by drizzle-kit. */
export const migrationsPath = join(root, 'drizzle')
